def opportunity_changes(current:list[dict],previous:dict|None,now:str,reg:dict)->dict:
    old={r['asset']:r for r in (previous or {}).get('candidates',[])};new={r['asset']:r for r in current}
    def state(r):return r.get('decision_metrics',{}).get('current_primary_hypothesis')
    changes={'new_candidates':[],'removed_candidates':[],'strengthening_candidates':[],'weakening_candidates':[],'newly_invalidated':[],'newly_overextended':[],'newly_confirmed_breakouts':[],'newly_entered_lower_range':[]}
    for asset in sorted(set(new)-set(old)):changes['new_candidates'].append({'asset':asset,'previous_state':None,'current_state':state(new[asset]),'score_change':new[asset]['decision_metrics']['decision_impact_score'],'reason':'NEW_TO_PACKET','timestamp':now})
    for asset in sorted(set(old)-set(new)):changes['removed_candidates'].append({'asset':asset,'previous_state':state(old[asset]),'current_state':None,'score_change':-float(old[asset].get('decision_metrics',{}).get('decision_impact_score') or 0),'reason':'REMOVED_FROM_TOP_INFORMATION_BUDGET','timestamp':now})
    for asset in sorted(set(old)&set(new)):
        before=float(old[asset].get('decision_metrics',{}).get('decision_impact_score') or 0);after=float(new[asset]['decision_metrics']['decision_impact_score']);target='strengthening_candidates' if after>before else 'weakening_candidates' if after<before else None
        if target:changes[target].append({'asset':asset,'previous_state':state(old[asset]),'current_state':state(new[asset]),'score_change':after-before,'reason':'DECISION_EVIDENCE_SCORE_CHANGED','timestamp':now})
        oc, nc=old[asset],new[asset]
        if oc.get('consolidation',{}).get('range_validity') is not False and nc['consolidation'].get('range_validity') is False:changes['newly_invalidated'].append({'asset':asset,'previous_state':'VALID','current_state':'INVALIDATED','score_change':after-before,'reason':'RANGE_VALIDITY_CHANGED','timestamp':now})
        if oc.get('momentum',{}).get('extension_risk')!='HIGH' and nc['momentum'].get('extension_risk')=='HIGH':changes['newly_overextended'].append({'asset':asset,'previous_state':oc.get('momentum',{}).get('extension_risk'),'current_state':'HIGH','score_change':after-before,'reason':'EXTENSION_RISK_INCREASED','timestamp':now})
        if oc.get('momentum',{}).get('stage')!='BREAKOUT_CONFIRMED' and nc['momentum'].get('stage')=='BREAKOUT_CONFIRMED':changes['newly_confirmed_breakouts'].append({'asset':asset,'previous_state':oc.get('momentum',{}).get('stage'),'current_state':'BREAKOUT_CONFIRMED','score_change':after-before,'reason':'BREAKOUT_CONFIRMED','timestamp':now})
        pos=nc['consolidation'].get('position_percent');oldpos=oc.get('consolidation',{}).get('position_percent')
        if pos is not None and 0<=pos<=30 and (oldpos is None or not 0<=oldpos<=30):changes['newly_entered_lower_range'].append({'asset':asset,'previous_state':oldpos,'current_state':pos,'score_change':after-before,'reason':'ENTERED_LOWER_30_PERCENT','timestamp':now})
    changes['rotation_state_change']={'previous':(previous or {}).get('btc_rotation',{}).get('preferred_state'),'current':reg.get('btc_rotation',{}).get('summary',{}).get('preferred_state')};changes['sector_leader_change']={'previous':(previous or {}).get('sector_leadership',{}).get('strongest_sector'),'current':(reg.get('leadership_rotation',{}).get('top_sectors') or [{}])[0].get('sector')};changes['capital_flow_change']={'previous':(previous or {}).get('capital_flow',{}).get('primary_state'),'current':reg.get('capital_flow',{}).get('summary',{}).get('primary_state')};return changes
def risk_records(candidates:list[dict],portfolio:dict,reg:dict)->list[dict]:
    risks=[];open_assets={r['asset'] for r in portfolio['open_positions']}
    def add(sev,asset,code,evidence,hypothesis,mitigation):risks.append({'severity':sev,'asset':asset,'code':code,'evidence':evidence,'affected_hypothesis':hypothesis,'current_position_exposure':asset in open_assets,'mitigation_condition':mitigation})
    if reg.get('market_regime',{}).get('summary',{}).get('crypto_regime')=='BEAR':add('HIGH','MARKET','BEAR_MARKET_REGIME','Research regime is BEAR','broad risk exposure','Regime improves and breadth confirms')
    for r in candidates:
        a=r['asset'];m=r['momentum'];c=r['consolidation'];v=r['validation'];e=r['evidence']
        if c.get('range_validity') is False:add('HIGH',a,'RANGE_INVALIDATION','Detected range is invalid',r['decision_metrics'].get('current_primary_hypothesis'),'Require a newly validated range')
        if m.get('extension_risk')=='HIGH':add('HIGH',a,'OVEREXTENSION','Momentum extension risk is HIGH','momentum continuation','Wait for extension to normalize')
        if not v.get('historical_sample_size'):add('MEDIUM',a,'LOW_SAMPLE_SIZE','No validated historical event sample','rotation or forecast confidence','Obtain adequate historical validation')
        if r['current_data'].get('freshness') not in {'FRESH',None}:add('HIGH',a,'STALE_DATA',r['current_data'].get('freshness'),'all current hypotheses','Refresh completed-candle data')
        if e.get('opposing_modules'):add('MEDIUM',a,'MODEL_CONFLICT',e['opposing_modules'],r['decision_metrics'].get('current_primary_hypothesis'),'Resolve module conflict manually')
    order={'CRITICAL':0,'HIGH':1,'MEDIUM':2,'LOW':3};return sorted(risks,key=lambda x:(order[x['severity']],not x['current_position_exposure'],x['asset'],x['code']))[:12]
